import{R as t,e as i,f as o,U as n}from"./chunks/framework.ywem4qy5.js";const g=JSON.parse('{"title":"Pipedrive","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/pipedrive.md","filePath":"integrations/crm/pipedrive.md","lastUpdated":1775908585000}'),r={name:"integrations/crm/pipedrive.md"};function a(l,e,s,p,h,d){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="pipedrive" tabindex="-1">Pipedrive <a class="header-anchor" href="#pipedrive" aria-label="Permalink to &quot;Pipedrive&quot;">​</a></h1><p>Follow the below steps to connect to the Pipedrive API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Pipedrive as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-pipedrive-api" tabindex="-1">Step 2. Connect to the Pipedrive API <a class="header-anchor" href="#step-2-connect-to-the-pipedrive-api" aria-label="Permalink to &quot;Step 2. Connect to the Pipedrive API&quot;">​</a></h3><ol><li>Go to <a href="https://www.pipedrive.com/" target="_blank">Pipedrive</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Personal Preferences</strong>.</li><li>Click on the <strong>API</strong> tab.</li><li>Copy the <strong>Your personal API token</strong> from Pipedrive and paste in the <strong>API Key</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const f=t(r,[["render",a]]);export{g as __pageData,f as default};
